import{_ as a,C as e,o as i,c as s,j as d,a as n,E as o,a3 as l}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"体用生克篇之三：三要灵应篇","description":"从耳闻、目见与当下情境，理解感象与克应的关系。","frontmatter":{"title":"体用生克篇之三：三要灵应篇","description":"从耳闻、目见与当下情境，理解感象与克应的关系。","category":"学习计划 · 第二阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/ti-yong-sheng-ke/three-essential-responses.md","filePath":"yijing/meihua-yishu/ti-yong-sheng-ke/three-essential-responses.md","lastUpdated":1787730063000}'),p={name:"yijing/meihua-yishu/ti-yong-sheng-ke/three-essential-responses.md"};function g(h,t,m,c,y,u){const r=e("DaoTextReading");return i(),s("div",null,[t[0]||(t[0]=d("h1",{id:"【体用生克篇之三】三要灵应篇",tabindex:"-1"},[n("【体用生克篇之三】三要灵应篇 "),d("a",{class:"header-anchor",href:"#【体用生克篇之三】三要灵应篇","aria-label":'Permalink to "【体用生克篇之三】三要灵应篇"'},"​")],-1)),t[1]||(t[1]=d("blockquote",null,[d("p",null,"本篇是梅花易数「感象」功夫的集大成。前几篇讲规则，这篇讲的是规则背后的感知状态。")],-1)),t[2]||(t[2]=d("hr",null,null,-1)),t[3]||(t[3]=d("h2",{id:"📜-原文",tabindex:"-1"},[n("📜 原文 "),d("a",{class:"header-anchor",href:"#📜-原文","aria-label":'Permalink to "📜 原文"'},"​")],-1)),o(r,{colophon:"三要灵应篇",tone:"ink",sections:[{id:"sec-01",label:"三要灵应篇序",showLabel:!0,sentences:[["夫《易》者，性理之学也。"],["性理，具于人心者也。"],["当其",{text:"方寸湛然",glossary:"g01"},"，",{text:"灵台皎洁",glossary:"g02"},"，无一毫之干，无一尘之累，斯时也，性理具在而《易》存吾心，浑然是《易》也，其先天之《易》也。"],["乃夫虑端一起，事根忽萌，物之着心，如云之蔽室，如尘之蒙镜，斯时也，",{text:"汩没茫昧",glossary:"g03"},"，而向之《易》存吾心者，泯焉尔。"],["故三要之妙，在于运耳、目、心三者之虚灵，",{text:"俾",glossary:"g04"},"应于事物也，耳之聪，目之明，吾心实总乎聪明。"],["盖事根于心，心该乎事，然事之未萌也，虽鬼神莫测其端，而吉凶祸福，无门可入。"],["故先师曰：「思虑未动，鬼神不知；不由乎我，更由乎谁？"],["」故事萌于心，鬼神知之矣。"],["吉凶悔吝有其数，然吾预知之，何道欤？"],["必曰：「求诸吾心易之妙而已矣。"],["」于是寂然不动，静虑诚存，观变玩占，运乎三要，必使视之不见，吾见之；听之不闻者，吾闻之；如形之见视，如音之见告，吾之了然鉴之。"],["则《易》之为卜筮之道，而《易》在吾心矣。"],["三要不虚，而灵应之妙斯得也。"],["是道也，寓至精至神之理，百姓日用而不知，安得",{text:"圆通三昧",glossary:"g05"},"者，与之论欤！"],["此先师刘先生（江夏人，号湛然子）得之王屋山人高处士云岩。"],["宝庆四年，仲夏既望，清灵子朱虚拜首序"]]},{id:"sec-02",label:"三要灵应篇",showLabel:!0,sentences:[["三要者，运耳、目、心三者之要也。"],["灵应者，灵妙而应验也。"],["夫耳之于听，目之于视，心之于思，三者为人一身之要，而万物之理不出于视听之外。"],["占决之际，",{text:"寂闻澄虑",glossary:"g06"},"，静观万物，而听其音，知吉凶，见其形，知善恶，察其理，知祸福，皆可为占卜之验。"],["如谷之应声，如影之随形，",{text:"灼然",glossary:"g07"},"可见也。"],["其理出于《周易》「远取诸物，近取诸身」之法。"],["是编则出于先贤先师，采世俗之语为例用之者：鬼谷子、严君平、东方朔、诸葛孔明；继而得者：邵康节、邵伯温、刘伯温、牛思晦、牛思继、高处士、刘湛然、富寿子、泰然子、朱清灵子。"],["其年代相传不一，而不知其姓名者不与焉。"],["原夫天高地厚，万物散殊，阴浊阴清，五气顺布，祸福莫逃乎数，吉凶皆有其机。"],["人为万物之灵，心乃一身之主，目寓而为形于色，耳得而为音于声，三要总之，万物备矣。"],["此乃天地万物之灵，而耳、目、心三者之要，故曰三要也。"],["是以遇吉兆而有吉，见凶识而不免乎凶。"],["物之圆者事成，缺事败。"],["此理断然，夫复何疑？"],["此乃占物克应，见吉则吉，遇凶则凶。"],["是以云开见日，事必增辉；烟雾障空，物当失色。"],["忽颠风而飘荡，遇震雷以虚惊。"],["月忽当面，宜近清光。"],["雨可沾衣，可蒙恩泽。"],["此乃仰观天文，以验人事。"],["重山为阻隔之际，重泽为浸润之深。"],["水流而事通，土积而事滞。"],["石乃坚心始得，沙乃放手即开。"],["浪激主波涛之惊，坡崩主田土之失。"],["旱沼之旁，心力俱竭，枯林之下，相貌皆衰。"],["此来俯察地理，以验人事。"],["适逢人品之来，实为事体之应。"],["故荣宦显官，宜见其贵；富商匠贾，可问乎财。"],["儿童哭泣忧子孙，吏卒叫嚣忌官讼。"],["二男二女，重婚之义；一僧一道，独处之端。"],["妇人笑语，则阴喜相逢；女子牵连，则阴私见累。"],["匠氏，主门庭改换；宰夫，则骨肉分离。"],["逢猎者，得野外之财；见渔者，有水边之利。"],["见妊妇，则事荫于内；遇",{text:"瞽者",glossary:"g10"},"，则虑根于心。"],["此乃人品之应，以验人事。"],["至于摇手而莫为，或掉头而不肯，拭目而喷嚏者方泣；搔首而弹垢者有忧。"],["足动者有行，交臂者有失。"],["屈指者多阻节，嘘气者主悲忧。"],["舌出掉者有是非，背相向者防闪失。"],["偶",{text:"攘臂",glossary:"g11"},"者，争夺乃得；偶下膝者，屈抑而求。"],["此乃「近取诸身」之应。"],["若逢童子授书，有词讼之端；主翁",{text:"笞仆",glossary:"g12"},"，防责罚之事。"],["讲论经史，事体徒间于虚说；语歌词曲，谋为转见悠扬。"],["见博赌，主争斗之财；遇题写，主文书之事。"],["偶携物者，受人提携；适挽手者，遇事牵连。"],["此乃人事之应。"],["及夫舟楫在水，凭其接引而行；车马登途，藉之负戴而往。"],["张弓挟矢者，必领荐；有箭无弓者，未可试。"],["持刀执刃，须求快利之方。"],["披甲操戈，可断刚强之柄。"],[{text:"缫丝",glossary:"g13"},"者，事务繁冗。"],["围棋者，眼目众多。"],["妆花刻果，终非结实之因。"],["书影描形，皆为装点之类。"],["络绎将成，可以问职。"],["笔墨俱在，可以求文。"],["偶",{text:"倾盖",glossary:"g14"},"者，主退权。"],["忽临镜者，可赴诏。"],["抱贵器者，有非常之用。"],["负大木者，有不小之财。"],["升斗宜量料而前，尺剪可裁度以用。"],["见",{text:"蹴球",glossary:"g15"},"，有人发剔。"],["开锁钥，遇事疏通。"],["逢补器，终久难坚。"],["值磨镜，再成始得。"],["顽斧磨钢者，迟钝得利。"],["快刀砍木者，利事伤财。"],["裁衣服者，破后方成。"],["造瓦器者，成后乃破。"],["奕棋者，取之以计。"],[{text:"张纲",glossary:"g16"},"者，摸之以空。"],["或持斧锯恐有伤，或涤壶觞恐有饮。"],["或挥扇者，有相招之义。"],["或污衣者，防谋害之侵。"],["此乃器物之应，即「远取诸物」之意。"],["虽云草木之无情，亦与卜筮而有应。"],["故芝兰为物之瑞，松柏为寿之坚。"],["遇椿桧，则岁久年深；遇",{text:"苗菰",glossary:"g17"},"，则朝生暮死。"],["占产占病，得之即死之兆。"],["枝叶飘零当萎谢，根核流落主牵连。"],[{text:"奇葩",glossary:"g18"},"端的虚花，",{text:"嘉果",glossary:"g19"},"可以结实。"],["此乃草木之应。"],["至于飞走，最有",{text:"祯祥",glossary:"g08"},"。"],["故乌鸦报灾，喜虫报喜，鸿雁主朋友之信，",{text:"蛇虺",glossary:"g09"},"防毒害之谋。"],["鼠啮衣，有小口之灾；雀噪檐，有远行之至。"],["犬斗恐招盗贼，鸡斗主有喧争。"],["牵羊者，喜庆将临，骑马者，出入皆利。"],["猿猴攀木，身心不定；鲤鱼出水，变化不凡。"],["绳拴马，疾病难安；架陷禽，囚人末脱。"],["此乃禽兽之应。"],["酒乃忘忧之物，药乃怯病之方。"],["故酒樽忽破，乐极生悲；医师道逢，难中有救。"],["藤萝之类堪依倚，虎豹之象可施威。"],["耕田锄地者，事势必翻。"],["破竹剖竿者，事势必顺。"],["春花秋月，虽无实而关景，夏绵冬葛，虽有用而背时。"],["凉扇，多主弃捐；晴伞，渐逢闲废。"],["泡沫电光，虚幻难信；蛛丝蚕茧，巧计方成。"],["此乃杂见观物之应。"],["若见物形，可知字体。"],["故石逢皮则破；人傍木为休；笠漂水畔，泣字分明。"],["火入山林，焚形可见。"],["三女有奸私之扰，三牛有奔走之忧。"],["一木两火，荣耀之光。"],["一水四鱼，鳏寡之象。"],["人继牛倒防失脱，人言犬中忧狱囚。"],["一斗入空门者，斗争。"],["两丝挂白木者，乐事。"],["一人立门，诸事有闪。"],["二人夹木，所问必来。"],["此为拆字之应。"],["复指物名，以",{text:"叶音义",glossary:"g20"},"。"],["如见鹿可以问禄，见蜂可以言封。"],["梨主分别，桃主逃走。"],["见李则问讼得理，逢冠则问名得官。"],["鞋为百事和谐，",{text:"阖",glossary:"g21"},"则诸事可合。"],["难以详备，在于变通。"],["此即物叶音之义。"],["及夫在我之身，实为彼事之应。"],["故我心忧者，彼事亦忧；我心乐者，彼事亦乐。"],["我适闲，彼当从容；我值忙，彼当窘迫。"],["此即自己之应，「近取诸身」之义。"],["欲究观人之道，须详系《易》之辞。"],["将叛者，其辞惭；将疑者，其辞支。"],["吉人之辞寡，躁人之辞多。"],["诬善之人，其辞游；失其守者，其辞屈。"],["此一动一静之应，「近取诸身」之义。"],["又推五行，须详八卦。"],["卦吉而应吉终吉，卦凶而应凶终凶。"],["卦应一吉一凶，事体半吉半凶。"],["明生克之理，察动静之机，事事相关，物物相合，此五行八卦及克应动静之理。"],["活法更存乎方寸，玄机又在于师传。"],["纵万象之纷纭，惟一理而融贯。"],["务要相机而发，须要临事而详。"],["此言占卜之理在于变通之妙。"],["嗟夫，",{text:"方朔覆射",glossary:"g23"},"，知事物之隐微。"],[{text:"诸葛马前",glossary:"g24"},"，定吉凶于顷刻。"],[{text:"皇甫坐端",glossary:"g25"},"之妙，",{text:"淳风鸟觉",glossary:"g26"},"之占，虽所用之有殊，诚此理之无异。"],["此言三要灵应妙处。"],["可以契鬼神之妙，可以会",{text:"着龟",glossary:"g27"},"之灵。"],["然",{text:"人非三世",glossary:"g28"},"，莫能造其玄；心非七窍，莫能悟其奥。"],["故得其说者，宜秘；非其人者，莫传。"],["轻泄天机，重遭",{text:"阴谴",glossary:"g22"},"。"],["造之深，可以入道。"],["用之久，可以通神。"],["此言灵应之妙，不可轻传妄授，宜秘之一人，之以重斯道也。"]]}],glossary:[{id:"g01",term:"方寸湛然",pinyin:"zhàn rán",meaning:"方寸即心，湛然：清澈安静"},{id:"g02",term:"灵台皎洁",pinyin:"jiǎo jié",meaning:"灵台即心，皎洁：明亮洁净"},{id:"g03",term:"汩没茫昧",pinyin:"gǔ mò máng mèi",meaning:"沉没混乱，昏昧不明"},{id:"g04",term:"俾",pinyin:"bǐ",meaning:"使，令"},{id:"g05",term:"圆通三昧",pinyin:"sān mèi",meaning:"佛教语，三昧即正定，圆通三昧指彻底通达的境界"},{id:"g06",term:"寂闻澄虑",pinyin:"chéng lǜ",meaning:"寂静地听，澄清思虑"},{id:"g07",term:"灼然",pinyin:"zhuó rán",meaning:"明显，清楚"},{id:"g08",term:"祯祥",pinyin:"zhēn xiáng",meaning:"吉祥的征兆"},{id:"g09",term:"蛇虺",pinyin:"shé huǐ",meaning:"毒蛇，虺为小毒蛇"},{id:"g10",term:"瞽者",pinyin:"gǔ zhě",meaning:"盲人"},{id:"g11",term:"攘臂",pinyin:"rǎng bì",meaning:"捋起袖子，表示奋力争夺"},{id:"g12",term:"笞仆",pinyin:"chī pú",meaning:"鞭打仆人"},{id:"g13",term:"缫丝",pinyin:"sāo sī",meaning:"从蚕茧中抽丝"},{id:"g14",term:"倾盖",pinyin:"qīng gài",meaning:"车盖相倾，指偶然相遇"},{id:"g15",term:"蹴球",pinyin:"cù qiú",meaning:"踢球"},{id:"g16",term:"张纲",pinyin:"zhāng gāng",meaning:"撒网捕鱼"},{id:"g17",term:"苗菰",pinyin:"miáo gū",meaning:"初生的菰草，朝生暮死之物"},{id:"g18",term:"奇葩",pinyin:"qí pā",meaning:"奇异的花，此处指华而不实"},{id:"g19",term:"嘉果",pinyin:"jiā guǒ",meaning:"好的果实，结实之象"},{id:"g20",term:"叶音义",pinyin:"yè yīn yì",meaning:"以物名的谐音取义"},{id:"g21",term:"阖",pinyin:"hé",meaning:"关闭，合拢"},{id:"g22",term:"阴谴",pinyin:"yīn qiǎn",meaning:"冥冥中的惩罚"},{id:"g23",term:"方朔覆射",pinyin:"—",meaning:"东方朔以布覆物令人猜测，知隐微之事"},{id:"g24",term:"诸葛马前",pinyin:"—",meaning:"诸葛亮马前课，顷刻定吉凶"},{id:"g25",term:"皇甫坐端",pinyin:"—",meaning:"皇甫真人坐而起卦之妙"},{id:"g26",term:"淳风鸟觉",pinyin:"—",meaning:"李淳风见鸟而占之法"},{id:"g27",term:"着龟",pinyin:"zhuó guī",meaning:"灼龟甲以占卜"},{id:"g28",term:"人非三世",pinyin:"—",meaning:"非经三世修炼，难造其玄"}],"aria-label":"三要灵应篇原文"}),t[4]||(t[4]=l("",86))])}const q=a(p,[["render",g]]);export{x as __pageData,q as default};
